/** Formal actual handoff, partial plan and single-part writers; fictional data and zero model calls. */
class SourcePartialPlanCoordinatorTest {
    SourceValuePartialIntentHandoffTest q;GenerationJdbcStoreTest db;SourcePlanPreparationCoordinator service;NewsValueSourcePlanPreparationService value;SourceStagePreparationService parts;FrozenSourceStagePlanService plans;Clock clock;String intent;int settings;boolean allowed=true;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(int count,boolean mixed)throws Exception{
        q=new SourceValuePartialIntentHandoffTest(){@Override GenerationJdbcStoreTest database(){return SourcePartialPlanCoordinatorTest.this.database();}};q.setup(count,mixed);var handoff=q.service.handoff(q.h.ref);intent=handoff.p2Owner();db=q.h.f.f;clock=Clock.fixed(q.h.f.clock.instant().plusSeconds(60),ZoneOffset.UTC);
        // Later current-ready rows cannot override the original P1 failures.
        for(var row:db.jdbc.queryForList("SELECT id,evidence_json FROM source_run_items")){String id=(String)row.get("id");var body=CanonicalJson.parse((String)row.get("evidence_json"));var identity=JsonMapper.shared().createObjectNode().put("namespace","article_url");identity.set("key",body.get("source_url"));String key=JdbcFrozenInputs.canonical(identity),entity="fictional-entity-"+id;db.jdbc.update("UPDATE source_run_items SET state='ready',entity_id=?,revision=4 WHERE id=?",entity,id);db.jdbc.update("INSERT INTO analyzed_entities(id,category,identity_key,identity_hash,title,summary,revision,first_recorded_at,analysis_state,legacy_flag,first_seen_business_date) VALUES(?,'news_tech',?,?,?,?,0,?,'pending',0,'2026-01-01')",entity,key,JdbcEntityDedup.identityHash("news_tech",key),body.get("title").asText(),body.get("source_summary").isNull()?null:body.get("source_summary").asText(),Timestamp.from(q.h.f.clock.instant().minusSeconds(1)));}
        plans=new FrozenSourceStagePlanService(new JdbcFrozenSourcePlans(db.source),q.h.f.p1.universes,clock,"fictional-owner");service=provider(db.writes,q.a.service);
    }
    SourcePlanPreparationCoordinator provider(SharedWriteExecutor writes,SourceDedupPartialDependencyPermitService permit){var deps=new SourceDedupDependencyService(q.a.observations,q.a.proven,permit);value=new NewsValueSourcePlanPreparationService(new JdbcFrozenSourcePlans(db.source),new JdbcFrozenSourceUniverses(db.source),q.h.f.p1.universes,plans,q.h.f.p1.collections,new NewsValueEligibilityService(new JdbcNewsDedupEligibility(db.source),new JdbcNewsValueEntities(db.source),q.h.f.p1.members,clock),deps,()->{settings++;return new FrozenGenerationSettings(1,List.of(),List.of());},clock,()->allowed,"2");parts=new SourceStagePreparationService(db.source,plans,q.h.f.p1.universes,q.h.f.p1.collections::read,clock,"fictional-owner",null,deps);return new SourcePlanPreparationCoordinator(q.h.f.p1.preparation,value,parts,q.service,q.h.proofs,new JdbcFrozenSourcePlans(db.source),writes,new DataSourceTransactionManager(db.source),clock,()->allowed,permit);}
    SourcePlanPreparationCoordinator.Prepared prepare(long part){return service.prepareValuePartial(intent,"fictional-run",q.h.ref,part);}
    @Test void Formal201MemberPreparationUsesOutsidePureBuildAndOneOriginalPartPerWriter()throws Exception{
        setup(201,true);int calls=db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class);value=spy(value);doAnswer(call->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());return call.callRealMethod();}).when(value).build(any());service=new SourcePlanPreparationCoordinator(q.h.f.p1.preparation,value,parts,q.service,q.h.proofs,new JdbcFrozenSourcePlans(db.source),db.writes,new DataSourceTransactionManager(db.source),clock,()->allowed,q.a.service);var first=prepare(0);assertEquals(201,first.plan().decisions().size());assertEquals(200,first.plan().chunks().stream().mapToInt(c->c.itemIds().size()).sum());assertTrue(first.plan().chunks().size()>1);assertEquals("partial",first.root().coverageState());assertEquals(first.plan().chunks().getFirst().snapshotJson(),first.root().snapshotJson());for(int n=1;n<first.plan().chunks().size();n++)assertEquals(first.plan(),prepare(n).plan());assertEquals(first.plan().chunks().size(),db.count("record_kind='logical_task' AND task_type='news_value'"));assertEquals(calls,db.jdbc.queryForObject("SELECT SUM(call_count) FROM jobs",Integer.class));int rows=db.count("1=1"),reads=settings;allowed=false;db.jdbc.execute("DROP TABLE source_run_items");db.jdbc.execute("DROP TABLE analyzed_entities");assertEquals(first,prepare(0));assertEquals(rows,db.count("1=1"));assertEquals(reads,settings);
    }
    @Test void AllFailedZeroValuePlanKeepsOriginalAcceptedDecisionAndNoSyntheticRoot()throws Exception{
        setup(1,false);var first=prepare(0);assertNull(first.root());assertTrue(first.plan().chunks().isEmpty());assertEquals(1,first.plan().decisions().size());assertEquals(SourcePartitionPlanner.Reason.NOT_AI_ELIGIBLE,first.plan().decisions().getFirst().reason());assertEquals(0,db.count("record_kind='logical_task' AND task_type='news_value'"));int rows=db.count("1=1"),reads=settings;allowed=false;db.jdbc.execute("DROP TABLE source_run_items");db.jdbc.execute("DROP TABLE analyzed_entities");assertEquals(first,prepare(0));assertEquals(rows,db.count("1=1"));assertEquals(reads,settings);
    }
    @Test void FailedPartAndActualPlanOrPartAckRecoverOnlyTheOriginalPlan()throws Exception{
        setup(101,true);String rejected=JdbcFrozenInputs.stableId("prepare-action",SourcePlanPreparationCoordinator.partAction(intent,0));db.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_partial_coordinator_failure CHECK(id<>'"+rejected+"')");assertThrows(RuntimeException.class,()->prepare(0));assertEquals(0,db.count("record_kind='logical_task' AND task_type='news_value'"));assertNotNull(q.h.f.readonly(()->new JdbcFrozenSourcePlans(db.source).immutableReceipt(intent)));int reads=settings;db.jdbc.execute(db.source instanceof org.h2.jdbcx.JdbcDataSource?"ALTER TABLE jobs DROP CONSTRAINT fictional_partial_coordinator_failure":"ALTER TABLE jobs DROP CHECK fictional_partial_coordinator_failure");assertNotNull(prepare(0).root());assertEquals(reads,settings);
        for(int loseAt:List.of(2,3)){setup(101,true);var fault=new DataSourceTransactionManager(db.source){int commits;@Override protected void doCommit(DefaultTransactionStatus status){super.doCommit(status);if(!TransactionSynchronizationManager.isCurrentTransactionReadOnly()&&++commits==loseAt)throw new org.springframework.transaction.TransactionSystemException("fictional partial coordinator ACK lost");}};var writes=new SharedWriteExecutor(new JdbcSharedWriteEntry(db.source),fault,()->25,n->{});service=provider(writes,q.a.service);var original=prepare(0);service=provider(db.writes,q.a.service);assertEquals(original,prepare(0));assertEquals(1,db.count("record_kind='logical_task' AND task_type='news_value'"));}
    }
    @Test void DefaultRouteGatesTransactionsAndNativeChangesCannotPrepareAPartialRoot()throws Exception{
        setup(1,false);service=provider(db.writes,null);assertThrows(RuntimeException.class,()->prepare(0));service=provider(db.writes,q.a.service);assertThrows(RuntimeException.class,()->service.prepareValue(intent,"fictional-run",q.h.ref,0));assertThrows(RuntimeException.class,()->q.h.f.p1.tx(()->prepare(0)));allowed=false;assertThrows(GenerationFlowService.CapacityGuarded.class,()->prepare(0));allowed=true;var changed=spy(q.a.service);doAnswer(call->{db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",q.a.f.plan.chunks().getFirst().rootId());return call.callRealMethod();}).when(changed).verify(any(),any());service=provider(db.writes,changed);assertThrows(RuntimeException.class,()->prepare(0));assertEquals(0,db.count("record_kind='logical_task' AND task_type='news_value'"));assertNull(q.h.f.readonly(()->new JdbcFrozenSourcePlans(db.source).immutableReceipt(intent)));service=provider(db.writes,q.a.service);assertNotNull(prepare(0));
    }
}
